mapper.select:


WHERE p.property_id IN

    #{id}

ORDER BY p.property_id

choose.otherwise:
CASE WHEN FLOOR((p.latitude - #{minLat}) / #{cellLat}) < 0 THEN 0
     WHEN FLOOR((p.latitude - #{minLat}) / #{cellLat}) > #{maxCellIndex} THEN #{maxCellIndex}
     ELSE CAST(FLOOR((p.latitude - #{minLat}) / #{cellLat}) AS INTEGER) END

CASE WHEN FLOOR((p.longitude - #{minLng}) / #{cellLng}) < 0 THEN 0
     WHEN FLOOR((p.longitude - #{minLng}) / #{cellLng}) > #{maxCellIndex} THEN #{maxCellIndex}
     ELSE CAST(FLOOR((p.longitude - #{minLng}) / #{cellLng}) AS INTEGER) END
